import{_ as t,o,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.9.1 — Upgrade Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/08-subscription-billing/3-9-1-upgrade-plan/spec.md","filePath":"feature/srs/08-subscription-billing/3-9-1-upgrade-plan/spec.md"}'),d={name:"feature/srs/08-subscription-billing/3-9-1-upgrade-plan/spec.md"};function i(c,e,r,l,s,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-9-1-—-upgrade-plan" tabindex="-1">FR 3.9.1 — Upgrade Plan <a class="header-anchor" href="#fr-3-9-1-—-upgrade-plan" aria-label="Permalink to &quot;FR 3.9.1 — Upgrade Plan&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.9.1</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-122</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Upgrade Plan</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Subscription &amp; Billing (<code>3.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-63, BR-64</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07, MSG50</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Aligns with <code>studio-and-agency-plan-catalog</code> (<code>STUDIO_FREE/PLUS/PRO</code> + <code>BASIC/PLUS/ENTERPRISE</code> + <code>1/3/6/12-month</code> cycles))</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Enable an Agency <code>Owner</code> to inspect the database-backed subscription plan catalog for their company type (<code>PERSONAL</code> Studio: <code>STUDIO_FREE</code>, <code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code>; <code>AGENCY</code> Business: <code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code>), preview exact mid-period proration/upgrade quotes (<code>GET /api/v1/billing/agencies/{agencyId}/upgrade-quote</code>), and initiate an upgrade or renewal order across <code>1</code>, <code>3</code>, <code>6</code>, or <code>12</code>-month billing cycles without permitting plan downgrades (<code>BR-63</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner</code>, I want to execute <strong>Upgrade Plan</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-20, BR-63, BR-64</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Strict Upgrade / Renewal Direction (<code>BR-63</code>):</strong> Only upward tier transitions (<code>STUDIO_FREE -&gt; STUDIO_PLUS -&gt; STUDIO_PRO</code> or <code>BASIC -&gt; PLUS -&gt; ENTERPRISE</code>) and same-tier cycle renewals (<code>PLUS</code> renewal) are permitted; downgrade requests are rejected (<code>400/409</code>, <code>MSG50</code>).</li><li><strong>2. Company-Type Line Isolation:</strong> <code>PERSONAL</code> Studio companies can only subscribe to <code>STUDIO_*</code> plans (<code>maxMembers = 1</code>); <code>AGENCY</code> Business companies can only subscribe to <code>BASIC / PLUS / ENTERPRISE</code> plans. Eligibility is re-verified atomically at order creation.</li><li><strong>3. Multi-Cycle Pricing &amp; Sale Discounts:</strong> Supports <code>1</code>, <code>3</code>, <code>6</code>, and <code>12</code>-month cycle prices (<code>billing_plan_cycle_prices</code>) and active Admin promotional sales (<code>AdminPlanController</code>), snapping immutable price version metadata onto <code>billing_orders</code>.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>subscription.plans.*</code>, <code>subscription.cycles.*</code>, <code>subscription.upgradeQuote.*</code> in <code>src/i18n/locales/{vi,en}/subscription.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>pages/agency/components/CompanyPlanSelector.tsx</code>, <code>AgencyPaymentPanel.tsx</code> (in-place Upgrade dialog), <code>/agency/:agencyId/subscription</code> on Web and <code>src/screens/billing/SubscriptionPlansScreen.tsx</code>, <code>StudioPlanCard.tsx</code>, <code>SubscriptionPlanCard.tsx</code>, <code>src/services/billingService.ts</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/agency/components/CompanyPlanSelector.tsx</code>, <code>AgencyPaymentPanel.tsx</code> (in-place Upgrade dialog), <code>/agency/:agencyId/subscription</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/SubscriptionPlansScreen.tsx</code>, <code>StudioPlanCard.tsx</code>, <code>SubscriptionPlanCard.tsx</code>, <code>src/services/billingService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/billing/plans?agencyId={agencyId}</code></td><td style="text-align:left;">Bearer (<code>Owner</code> / Agency member)</td><td style="text-align:left;"><code>BillingPlanController.listPlans()</code> -&gt; returns active <code>billing_plan_versions</code> &amp; <code>billing_plan_cycle_prices</code> filtered by company type (<code>PERSONAL</code> vs <code>AGENCY</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/public/billing/plans</code></td><td style="text-align:left;">Public (<code>Guest</code>)</td><td style="text-align:left;"><code>PublicBillingPlanController</code> -&gt; read-only public pricing page catalog</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/billing/agencies/{agencyId}/subscription</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>BillingController</code> -&gt; returns current <code>agency_subscriptions</code> entitlement, period bounds, and renewal eligibility</td></tr><tr><td style="text-align:left;">`GET /api/v1/billing/agencies/{agencyId}/upgrade-quote?planCode={code}&amp;periodMonths={1</td><td style="text-align:left;">3</td><td style="text-align:left;">6</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/billing/agencies/{agencyId}/orders</code></td><td style="text-align:left;">Bearer (<code>Owner</code>) + <code>Idempotency-Key</code></td><td style="text-align:left;"><code>BillingController.createAgencyOrder()</code> -&gt; creates SePay VietQR <code>UPGRADE</code> or <code>RENEW</code> order in <code>billing_orders</code></td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-9-2-make-payment-sepay/spec.html">FR 3.9.2 — Make Payment (SePay)</a> · <a href="./../../../modules/02-agency-studio-plans/studio-and-agency-plan-catalog/spec.html"><code>studio-and-agency-plan-catalog</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
